fn solve(a: i8, b: i8, s: Vec<char>) -> Vec<char> {
    // The expected length is a + b + 1
    let expected_len = (a + b + 1) as usize;
    if s.len() != expected_len {
        return vec!['N', 'o'];
    }

    // The hyphen must appear exactly once, and at index a.
    let hyphen_pos = a as usize;
    let mut hyphen_count = 0;

    for (i, &ch) in s.iter().enumerate() {
        if ch == '-' {
            hyphen_count += 1;
            // If the hyphen is not at the required position, it's invalid.
            if i != hyphen_pos {
                return vec!['N', 'o'];
            }
        } else if !ch.is_digit(10) {
            // Any character other than a digit or hyphen invalidates the pattern.
            return vec!['N', 'o'];
        }
    }

    // Ensure there is exactly one hyphen.
    if hyphen_count != 1 {
        return vec!['N', 'o'];
    }

    vec!['Y', 'e', 's']
}

fn main() {
    // Some quick tests
    assert_eq!(solve(3, 2, "123-45".chars().collect()), vec!['Y','e','s']);
    assert_eq!(solve(3, 2, "12-345".chars().collect()), vec!['N','o']); // hyphen at pos 2, not 3
    assert_eq!(solve(1, 1, "1-2".chars().collect()), vec!['Y','e','s']);
    assert_eq!(solve(1, 1, "12-".chars().collect()), vec!['N','o']); // hyphen at pos 2, not 1
    assert_eq!(solve(2, 2, "12--3".chars().collect()), vec!['N','o']); // two hyphens
    println!("All tests passed!");
}